// Import of required libraries
import { test, expect, getBaseUrl, newSkyrampPlaywrightPage } from '@skyramp/skyramp';
import { searchOwnersByLastName } from './skyrampUtils';

const pageTimeout = 15000;

// URL for test requests
const baseUrl = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:4200");

test.use({
    viewport: { width: 1280, height: 900 },
});

test('testUi', async ({ page }) => {
    test.setTimeout(158000);

    // set default timeout for all locator/page actions in this test
    page.setDefaultTimeout(pageTimeout);
    // Wrap playwright page with Skyramp page
    page = newSkyrampPlaywrightPage(page);

    const pageErrors: string[] = [];
    page.on('pageerror', (error: Error) => pageErrors.push(error.message));

    await page.goto(baseUrl);
    await page.getByRole("button", { name: "Owners" }).click();
    await page.getByRole("link", { name: "Search" }).click();
    await page.waitForLoadState('networkidle');
    await page.locator("#ownersTable").waitFor({ state: 'visible', timeout: 10000 });
    await expect(page.locator("#ownersTable table tbody td")).toHaveCount(50);
    await expect(page.locator("#ownersTable")).toBeVisible();

    await searchOwnersByLastName(page, "Zzzzqqq");
    await expect(page.getByText("No owners found with a last")).toContainText("No owners found with a last name starting with \"Zzzzqqq\". Try a shorter search, or clear the box to list everyone.");
    await expect(page.locator("app-owner-list .alert")).toHaveClass("alert alert-info");
    await expect(page.locator("#ownersTable")).toHaveCount(0);
    await expect(page.locator("#ownersTable table tbody td")).toHaveCount(0);

    await searchOwnersByLastName(page, "");
    await expect(page.locator("#ownersTable table tbody td")).toHaveCount(50);
    await expect(page.locator("app-owner-list .alert")).toHaveCount(0);
    await expect(page.locator("#ownersTable")).toBeVisible();
    await expect(page.getByRole("link", { name: "George Franklin" })).toBeVisible();

    expect(pageErrors, 'no uncaught page errors').toEqual([]);
});
